{
  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello कांजी जी आपको कौन सा product चाहिए please details बता दीजिए।"
    },
    {
      "i": 1,
      "speaker": "caller",
      "text": "Hello."
    },
    {
      "i": 2,
      "speaker": "caller",
      "text": "Madam मुझे बाहर निकलना है रात को।"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "Thank you for sharing your requirement."
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "क्या आप अपने इस्तेमाल के लिए कोई वाहन या car से जुड़ा product लेना चाहते हैं?"
    },
    {
      "i": 5,
      "speaker": "bot",
      "text": "कृपया confirm कर दीजिए ताकि मैं आपकी मदद कर सकूं."
    },
    {
      "i": 6,
      "speaker": "caller",
      "text": "हाँ।"
    },
    {
      "i": 7,
      "speaker": "caller",
      "text": "जी Madam."
    },
    {
      "i": 8,
      "speaker": "caller",
      "text": "हाँ ले लीजिए।"
    },
    {
      "i": 9,
      "speaker": "bot",
      "text": "आपको car जो आमतौर पे journey या transport के लिए इस्तेमाल होती है यही चाहिए ना?"
    },
    {
      "i": 10,
      "speaker": "caller",
      "text": "हाँ yes sir."
    },
    {
      "i": 11,
      "speaker": "caller",
      "text": "हाँ।"
    },
    {
      "i": 12,
      "speaker": "bot",
      "text": "ठीक है मैं Tanya बोल रही हूं IndiaMART से।"
    },
    {
      "i": 13,
      "speaker": "bot",
      "text": "आपको मैं seller details WhatsApp पे भेज दूंगी जिनसे आप details और price confirm कर सकते हैं।"
    },
    {
      "i": 14,
      "speaker": "caller",
      "text": "क्या बात है जी?"
    }
  ]
}
